      if (tt > 1.0) tt -= 1.0;
      if (tt < 1.0/6.0) return p + (q - p) * 6.0 * tt;
      if (tt < 1.0/2.0) return q;
      if (tt < 2.0/3.0) return p + (q - p) * (2.0/3.0 - tt) * 6.0;
